// Apply Community Token Art
// Author: PrototypeESBU
// v1.0
// Requires: Shadowdark Community Tokens module installed.
// Description: Updates monsters in the current scene and actors tab that have the default "red cowl" and "eyes" monster token and portrait art with matching artwork from the Shadowdark Community Tokens project. 
// --------------------------------
const update_NPC_in_Scene = true;
const update_NPC_in_ActorsTab = true;
// --------------------------------

const defaults = [
    "systems/shadowdark/assets/tokens/cowled_token.webp",
    "modules/shadowdark-community-content/assets/tokens/default_monster.webp"
]

let tokensUpdated = 0;
let portraitsUpdated = 0;

if (!game.modules.get("shadowdark-community-tokens").active) {
    ui.notifications.error("ERROR: Install and activate the shadowdark-community-tokens module");
    return;
}
const monsters = await game.packs.get("shadowdark.monsters");

if (update_NPC_in_Scene) {
    for (const token of game.scenes.active.tokens) {
        const actor = game.actors.get(token.actorId);
        if (actor.type !== "NPC") continue;

        if (defaults.includes(token.texture.src)) {
            const art = await getMonsterArt(actor.name);
            if (art) {
                console.log(`Token: ${actor.name}\n Art:${art.token}`);
                await token.update({"texture.src": art.token});
                tokensUpdated++;
            }
        }
    }
}

if (update_NPC_in_ActorsTab) {
    for (const actor of game.actors) {
        if (actor.type !== "NPC") continue;

        if (defaults.includes(actor.prototypeToken.texture.src) || defaults.includes(actor.img)) {
            const art = await getMonsterArt(actor.name);
            if (art) {
                if (defaults.includes(actor.prototypeToken.texture.src)){
                    console.log(`Actor Tab Token: ${actor.name}\n Art:${art.token}`);
                    await actor.update({"prototypeToken.texture.src": art.token});
                    tokensUpdated++;
                }

                if (defaults.includes(actor.img))  {
                    console.log(`Portrait: ${actor.name}`);
                    await actor.update({"img": art.portrait});
                    portraitsUpdated++
                }
            }
        };
    }
}

async function getMonsterArt(name){
    const monster = monsters.index.find(x => x.name === name);
    if (monster) {
        const monsterObj = await fromUuid(monster.uuid);
        return {
            token: monsterObj.prototypeToken.texture.src,
            portrait: monsterObj.img
        }
    }
    return null;
}

ui.notifications.info(`${tokensUpdated} tokens and ${portraitsUpdated} portraits updated.`);
